public abstract class Account{private final String owner;protected double balance;protected Account(String o,double b){if(o==null||o.isBlank()||b<0)throw new IllegalArgumentException();owner=o;balance=b;}public void deposit(double a){if(a<=0)throw new IllegalArgumentException();balance+=a;}public abstract double monthlyFee();public double balanceAfterMonthlyFee(){return balance-monthlyFee();}public String owner(){return owner;}}
